    }



    private UnityEngine.Vector2 WorldToScreenPos(Virial.Compat.Vector2 worldPos)
    {
        return UnityHelper.WorldToScreenPoint(NebulaGameManager.Instance!.WideCamera.ConvertToWorldPos(worldPos).AsUnityVector3(), LayerExpansion.GetDefaultLayer());
    }
    public void ShowStickerOverlay(Virial.Media.GUIWidget widget, float duration, Virial.Compat.Vector2 stuckPosition)
    {
        var lifespan = FunctionalLifespan.GetTimeLifespan(duration);
        NebulaManager.Instance.RegisterStaticPopup(() => lifespan.IsDeadObject, () => !NebulaInput.SomeUiIsActive && lifespan.IsAliveObject, () => (widget, () => WorldToScreenPos(stuckPosition), null));
    }
    public void ShowStickerOverlay(Virial.Media.GUIWidget widget, Virial.Compat.Vector2 stuckPosition, Func<bool> isFinallyDead, Func<bool> predicate) 
    {
        NebulaManager.Instance.RegisterStaticPopup(isFinallyDead, predicate, () => (widget, () => WorldToScreenPos(stuckPosition), null));
    }
    public void ShowOverlay(Virial.Media.GUIWidget widget, GUIClickable? clickable = null) => NebulaManager.Instance?.SetHelpWidget(clickable?.uiElement, widget);

    public void HideOverlay() => NebulaManager.Instance.HideHelpWidget();

    public void HideOverlayIf(GUIClickable? clickable) => NebulaManager.Instance.HideHelpWidgetIf(clickable?.uiElement);


    public void MoveGUIContent(GUIAlignment alignment, GameObject content, Size contentSize, Size screenSize, float? z = null)
    {
        float x = 0f;
        float y = 0f;
        if (screenSize.Width > contentSize.Width)
        {
            var diff = (screenSize.Width - contentSize.Width) * 0.5f;
            if (alignment.HasFlag(GUIAlignment.Left)) x -= diff;
            if (alignment.HasFlag(GUIAlignment.Right)) x += diff;
        }
        if (screenSize.Height > contentSize.Height)
        {
            var diff = (screenSize.Height - contentSize.Height) * 0.5f;
            if (alignment.HasFlag(GUIAlignment.Bottom)) y -= diff;
            if (alignment.HasFlag(GUIAlignment.Top)) y += diff;
        }
        z ??= content.transform.localPosition.z;
        content.transform.localPosition = new(x, y, z.Value);
    }
}

public class GUIScreenImpl : GUIScreen
{
    GameObject myScreen;
    Anchor myAnchor;
    Size screenSize;

    public GUIScreenImpl(Anchor anchor,Size screenSize, Transform? parent, UnityEngine.Vector3 localPos)
    {
        this.myAnchor = anchor;
        this.screenSize = screenSize;
        this.myScreen = UnityHelper.CreateObject("Screen", parent, localPos, LayerExpansion.GetUILayer());
    }

    public void SetWidget(Virial.Media.GUIWidget? widget, out Size actualSize)
    {
        if (!myScreen)
        {
            actualSize = new(0f, 0f);
            return;
        }

        myScreen.ForEachChild((Il2CppSystem.Action<GameObject>)(obj => GameObject.Destroy(obj)));

        if (widget != null)
        {
            var obj = widget.Instantiate(myAnchor, screenSize, out actualSize);
            if (obj != null) obj.transform.SetParent(myScreen.transform, false);
        }
        else
        {
            actualSize = new(0f, 0f);
        }
    }
}

