    public static void PlaySE(NebulaAudioClip clip, bool oneshot = false, float volume = 0.8f, float pitch = 1.0f)
    {
        if (oneshot)
            AmongUsLLImpl.SoundManagerInstance.PlayOneShot(audioMap[clip], false, volume).pitch = pitch;
        else
            AmongUsLLImpl.SoundManagerInstance.PlaySound(audioMap[clip],false,volume).pitch = pitch;
    }

    public static AudioClip GetAudioClip(NebulaAudioClip clip) => audioMap[clip];

    public static AudioSource PlaySE(NebulaAudioClip clip, Vector2 pos, float minDistance, float maxDistance, float volume = 1f, bool loop = false) => PlaySE(audioMap[clip], pos, minDistance, maxDistance, volume, loop);

    public static AudioSource PlaySE(AudioClip clip,Vector2 pos,float minDistance,float maxDistance, float volume = 1f, bool loop = false)
    {
        var audioSource = UnityHelper.CreateObject<AudioSource>("SEPlayer", null, pos);

        audioSource.volume = volume;

        audioSource.transform.position = pos;
        audioSource.priority = 0;
        audioSource.spatialBlend = 1f;
        audioSource.clip = clip;
        audioSource.loop = loop;
        audioSource.playOnAwake = false;
        audioSource.maxDistance = maxDistance;
        audioSource.minDistance = minDistance;
        audioSource.rolloffMode = UnityEngine.AudioRolloffMode.Linear;
        audioSource.outputAudioMixerGroup = AmongUsLLImpl.SoundManagerInstance.SfxChannel;
        audioSource.Play();

        IEnumerator CoPlay()
        {
            Camera.main.gameObject.TryGetComponent<AudioListener>(out var listener);
            var listenerTransform = listener.transform;
            var audioSourceTransform = audioSource.transform;
            while (audioSource && audioSource.isPlaying)
            {
                if (listener)
                {
                    //至近距離の音は指向性を無くす
                    float distance = listenerTransform.GetPositionFast().Distance(audioSourceTransform.GetPositionFast());
                    audioSource.spatialBlend = distance < 0.5f ? 0f : distance < 1.5f ? distance - 0.5f : 1f;
                }
                yield return null;
            }
            if(audioSource) GameObject.Destroy(audioSource.gameObject);
            yield break;
        }

        NebulaManager.Instance.StartCoroutine(CoPlay().WrapToIl2Cpp());
        return audioSource;
    }

    public static readonly RemoteProcess<(NebulaAudioClip clip, Vector2 pos, float minDistance, float maxDistance)> RpcPlaySE = new(
        "PlaySE",
        (message, _) => PlaySE(message.clip, message.pos, message.minDistance, message.maxDistance)
    );

    public static TextMeshNoS InstantiateText(string objName, Transform? parent, Vector3 localPos, FontAssetNoS font, float size, Virial.Text.TextAlignment textAlignment, Vector2 pivot,string text,UnityEngine.Color color, bool showOnlyInMask = false)
    {
        var textObj = UnityHelper.CreateObject<TextMeshNoS>(objName, parent, localPos);
        textObj.Font = font;
        textObj.FontSize = size;
        textObj.TextAlignment = textAlignment;
        textObj.Pivot = pivot;
        textObj.Text = text;
        textObj.Material = new(showOnlyInMask ? MeshRendererMaskedShader : MeshRendererShader);
        textObj.Color = color;
        return textObj;
    }
}

